The ideal solution would involve the following key code changes:

1.  **New file `src/adapters/http/rate_limiter.h`:**
    ```c
    #ifndef RATE_LIMITER_H
    #define RATE_LIMITER_H

    // Forward declarations to avoid circular dependencies
    struct AppContext;
    struct HttpRequest;

    /**
     * @brief Middleware to rate limit requests based on IP.
     * @param context The application context, containing config and cache connections.
     * @param request The incoming HTTP request, containing the client IP.
     * @return 0 if the request is allowed, 1 if it should be rejected (rate-limited).
     */
    int rate_limit_middleware(struct AppContext* context, struct HttpRequest* request);

    #endif // RATE_LIMITER_H
    ```

2.  **New file `src/adapters/http/rate_limiter.c`:**
    ```c
    #include "rate_limiter.h"
    #include "../cache/redis_cache.h"
    #include "../../shared/config_loader.h"
    #include <stdio.h>
    #include <string.h>

    int rate_limit_middleware(struct AppContext* context, struct HttpRequest* request) {
        char redis_key[256];
        snprintf(redis_key, sizeof(redis_key), "rate_limit:%s", request->client_ip);

        long count = redis_incr(context->redis_conn, redis_key);

        if (count == -1) { // Redis error
            log_error("Rate limiter failed to increment key: %s", redis_key);
            return 0; // Fail open to not block users
        }

        if (count == 1) {
            // First request in the window, set expiration
            redis_expire(context->redis_conn, redis_key, 60);
        }

        if (count > context->config.search_rate_limit_per_minute) {
            return 1; // Rate-limited
        }

        return 0; // Allowed
    }
    ```

